ucs.kql:
let LookbackDays = 30d;
let SuspiciousChildren = dynamic(["powershell.exe","pwsh.exe","rundll32.exe","cmd.exe","wscript.exe","cscript.exe","mshta.exe"]);
let GoogleLegit = dynamic([@"c:\program files\google\", @"c:\program files (x86)\google\"]);
DeviceProcessEvents
| where Timestamp > ago(LookbackDays)
| where InitiatingProcessFileName in~ ("GoogleUpdate.exe","GoogleUpdateSetup.exe")
| where FileName in~ (SuspiciousChildren)
| extend ParentLower = tolower(InitiatingProcessFolderPath)
| where not(ParentLower startswith @"c:\program files\google\")
      and not(ParentLower startswith @"c:\program files (x86)\google\")
| project Timestamp, DeviceName, AccountName, InitiatingProcessFileName, InitiatingProcessFolderPath, InitiatingProcessSHA256, FileName, ProcessCommandLine, SHA256
| order by Timestamp desc
